UPDATE T_BRAIN_NOTE
   SET  TITLE      = #{title}
       ,BODY       = #{body}
       ,TOPICS     = #{topics}
       ,UPDATED_AT = NOW()
 WHERE ID = #{id}
   AND USER_ID = #{userId}

mapper.delete:
DELETE FROM T_BRAIN_LINK
 WHERE USER_ID = #{userId}
   AND (FROM_ID = #{id} OR TO_ID = #{id})

mapper.select:
SELECT  N.ID AS "id", N.KIND AS "kind", N.TITLE AS "title"
  FROM T_BRAIN_LINK L
  JOIN T_BRAIN_NOTE N ON N.ID = L.TO_ID AND N.USER_ID = L.USER_ID
 WHERE L.USER_ID = #{userId}
   AND L.FROM_ID = #{id}
 ORDER BY N.ID

SELECT  N.ID AS "id", N.KIND AS "kind", N.TITLE AS "title"
  FROM T_BRAIN_LINK L
  JOIN T_BRAIN_NOTE N ON N.ID = L.FROM_ID AND N.USER_ID = L.USER_ID
 WHERE L.USER_ID = #{userId}
   AND L.TO_ID = #{id}
 ORDER BY N.ID DESC

SELECT  N.ID AS "id", N.KIND AS "kind", N.TITLE AS "title", N.TOPICS AS "topics"
  FROM T_BRAIN_NOTE N
 WHERE N.USER_ID = #{userId}
 ORDER BY N.UPDATED_AT DESC
 LIMIT #{limit}

SELECT L.FROM_ID AS "fromId", L.TO_ID AS "toId"
  FROM T_BRAIN_LINK L
 WHERE L.USER_ID = #{userId}

SELECT  ID           AS "id"
       ,SOURCE_HASH  AS "storedHash"
       ,MD5(BODY)    AS "bodyHash"
  FROM T_BRAIN_NOTE
 WHERE USER_ID = #{userId}
   AND SOURCE_KEY = #{key}

