       ,BODY        = #{body}
       ,TOPICS      = #{topics}
       ,SOURCE_HASH = #{hash}
       ,UPDATED_AT  = NOW()
 WHERE USER_ID = #{userId}
   AND ID = #{id}
   AND MD5(BODY) = SOURCE_HASH
